func TestWriteIndex(t *testing.T) {
	dir := newRepo(t)
	en := readFile(t, dir, indexEN)
	wantEN := "# Architecture decision records\n" +
		"\n" +
		"<!-- Generated by make gen. Do not edit. -->\n" +
		"\n" +
		fmt.Sprintf(indexEnglish.intro, "[TPL-0001](template/TPL-0001-format.md)") + "\n" +
		"\n" +
		"## Project decisions\n" +
		"\n" +
		"| ID | Decision | Status | Date |\n" +
		"|---|---|---|---|\n" +
		"| [ADR-0001](ADR-0001-use-postgresql.md) | Use PostgreSQL | accepted | 2026-11-17 |\n" +
		"\n" +
		"## Template decisions\n" +
		"\n" +
		"| ID | Decision | Status | Date |\n" +
		"|---|---|---|---|\n" +
		"| [TPL-0001](template/TPL-0001-format.md) | Record decisions | accepted | 2026-11-17 |\n" +
		"| [TPL-0002](template/TPL-0002-use-sqlite.md) | Use SQLite | superseded by [ADR-0001](ADR-0001-use-postgresql.md) | 2026-11-17 |\n"
	if en != wantEN {
		t.Errorf("README.md:\n%s\nwant:\n%s", en, wantEN)
	}

	ja := readFile(t, dir, indexJA)
	wantJA := "# アーキテクチャの決定の記録\n" +
		"\n" +
		"<!-- Generated by make gen. Do not edit. -->\n" +
		"\n" +
		fmt.Sprintf(indexJapanese.intro, "[TPL-0001](template/TPL-0001-format.ja.md)") + "\n" +
		"\n" +
		"## 利用者の決定\n" +
		"\n" +
		"| ID | 決定 | 状態 | 日付 |\n" +
		"|---|---|---|---|\n" +
		"| [ADR-0001](ADR-0001-use-postgresql.ja.md) | PostgreSQL を使う | accepted | 2026-11-17 |\n" +
		"\n" +
		"## テンプレートの決定\n" +
		"\n" +
		"| ID | 決定 | 状態 | 日付 |\n" +
		"|---|---|---|---|\n" +
		"| [TPL-0001](template/TPL-0001-format.ja.md) | 決定を記録する | accepted | 2026-11-17 |\n" +
		"| [TPL-0002](template/TPL-0002-use-sqlite.ja.md) | SQLite を使う | 次の記録が置き換えた：[ADR-0001](ADR-0001-use-postgresql.ja.md) | 2026-11-17 |\n" +
		"\n" +
		i18n.Marker("README.md", []byte(en)) + "\n"
	if ja != wantJA {
		t.Errorf("README.ja.md:\n%s\nwant:\n%s", ja, wantJA)
	}

	// The marker makes the pair pass the translation check.
	findings, err := i18n.Check(os.DirFS(dir), []string{indexJA, indexEN})
	if err != nil || len(findings) > 0 {
		t.Errorf("i18n.Check() = %v, %v; want no findings", findings, err)
	}

	// A second run changes nothing.
	var out bytes.Buffer
	if err := WriteIndex(openRoot(t, dir), &out); err != nil {
		t.Fatal(err)
	}
	if out.Len() > 0 {
		t.Errorf("a second WriteIndex() reported %q, want nothing", out.String())
	}
}

func TestWriteIndexCases(t *testing.T) {
	tests := []struct {
		name    string
		files   map[string]string
		want    []string // lines of README.md
		wantJA  []string // lines of README.ja.md
		without []string // lines of neither
	}{
		{
			name:   "no records",
			files:  map[string]string{"docs/adr/template/.keep": ""},
			want:   []string{"None yet.", strings.Replace(indexEnglish.intro, "%s", "TPL-0001", 1)},
			wantJA: []string{"まだない。"},
		},
		{
			name: "a proposed record does not supersede",
			files: map[string]string{
				tpl1EN: recordText(enRecord, "TPL-0001", "Record decisions", ""),
				adr1EN: strings.Replace(recordText(enRecord, "ADR-0001", "Replace", "supersedes: [TPL-0001]"),
					"status: accepted", "status: proposed", 1),
			},
			without: []string{"superseded by"},
		},
		{
			name: "two records supersede one, and a missing translation falls back to English",
			files: map[string]string{
				tpl1EN:                   recordText(enRecord, "TPL-0001", "Record decisions", ""),
				adr1EN:                   recordText(enRecord, "ADR-0001", "First | second", "supersedes: [TPL-0001]"),
				"docs/adr/ADR-0002-b.md": recordText(enRecord, "ADR-0002", "B", "supersedes: [TPL-0001]"),
			},
			want: []string{
				"| [ADR-0001](ADR-0001-use-postgresql.md) | First \\| second | accepted | 2026-11-17 |",
				"| [TPL-0001](template/TPL-0001-format.md) | Record decisions | superseded by [ADR-0001](ADR-0001-use-postgresql.md), [ADR-0002](ADR-0002-b.md) | 2026-11-17 |",
			},
			wantJA: []string{
				"| [ADR-0001](ADR-0001-use-postgresql.md) | First \\| second | accepted | 2026-11-17 |",
				"| [TPL-0001](template/TPL-0001-format.md) | Record decisions | 次の記録が置き換えた：[ADR-0001](ADR-0001-use-postgresql.md)、[ADR-0002](ADR-0002-b.md) | 2026-11-17 |",
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := t.TempDir()
			for name, content := range tt.files {
				writeFile(t, dir, name, content)
			}
			writeIndex(t, dir)
			en := strings.Split(readFile(t, dir, indexEN), "\n")
			ja := strings.Split(readFile(t, dir, indexJA), "\n")
			for _, line := range tt.want {
				if !slices.Contains(en, line) {
					t.Errorf("README.md lacks the line %q:\n%s", line, strings.Join(en, "\n"))
				}
			}
			for _, line := range tt.wantJA {
				if !slices.Contains(ja, line) {
					t.Errorf("README.ja.md lacks the line %q:\n%s", line, strings.Join(ja, "\n"))
				}
			}
			for _, text := range tt.without {
				if joined := strings.Join(en, "\n"); strings.Contains(joined, text) {
					t.Errorf("README.md contains %q:\n%s", text, joined)
				}
			}
		})
	}
}

func TestSeal(t *testing.T) {
	dir := newRepo(t)
	writeFile(t, dir, "docs/adr/template/README.md", "# Template decisions\n")
	var out bytes.Buffer
	if err := Seal(openRoot(t, dir), &out); err != nil {
		t.Fatal(err)
	}
	if out.Len() > 0 {
		t.Errorf("Seal() after a README changed reported %q, want nothing", out.String())
	}
	var want strings.Builder
	for _, name := range []string{"TPL-0001-format.ja.md", "TPL-0001-format.md", "TPL-0002-use-sqlite.ja.md", "TPL-0002-use-sqlite.md"} {
		sum := sha256.Sum256([]byte(readFile(t, dir, templateDir+"/"+name)))
		want.WriteString(hex.EncodeToString(sum[:]) + "  " + name + "\n")
	}
	if got := readFile(t, dir, cks); got != want.String() {
		t.Errorf("checksums.txt:\n%s\nwant:\n%s", got, want.String())
	}

	edit(tpl1EN, "Why decide.", "Why we decide.")(t, dir)
	if err := Seal(openRoot(t, dir), &out); err != nil {
		t.Fatal(err)
	}
	if got := out.String(); got != cks+": updated\n" {
		t.Errorf("Seal() reported %q, want %q", got, cks+": updated\n")
	}
}

func TestSealWithoutTemplateDirectory(t *testing.T) {
	dir := t.TempDir()
	if err := Seal(openRoot(t, dir), &bytes.Buffer{}); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(dir + "/" + cks); !os.IsNotExist(err) {
		t.Errorf("Seal() without %s/ wrote %s", templateDir, cks)
	}
}
